def matrix_chain_order(arr):
    def cost(i, j):            # multiply matrices i..j
        if i >= j:
            return 0
        return min(cost(i, k) + cost(k + 1, j) + arr[i - 1] * arr[k] * arr[j]
                   for k in range(i, j))
    return cost(1, len(arr) - 1)

